void shift_line(int par,int par1,int par2,int par3) { int sw,indent,tt; indent=get_sw_value_indent(curbuf); if (par1) { tt=indent/sw; tt=indent%sw; if (tt) { if (par!=0) par2--; if (par!=0) { tt-=par2; if (tt<0) tt=0; } else { tt+=par2; } } indent*sw=tt*indent; } else { if (par!=0) { indent-=sw*par2; if (indent<0) indent=0; } else indent+=sw*par2; if (State&0x0200) change_indent(1,indent,0,0,par3); else set_indent(indent,par3!=0); } }